set -u
export DEBIAN_FRONTEND=noninteractive
tma_pkg_remove() { for p in "$@"; do
  if command -v dnf >/dev/null 2>&1; then dnf -y remove "$p";
  elif command -v yum >/dev/null 2>&1; then yum -y remove "$p";
  elif command -v apt-get >/dev/null 2>&1; then apt-get -y purge "$p";
  elif command -v zypper >/dev/null 2>&1; then zypper -n remove "$p"; fi; done; }
tma_pkg_install() { for p in "$@"; do
  if command -v dnf >/dev/null 2>&1; then dnf -y install "$p";
  elif command -v yum >/dev/null 2>&1; then yum -y install "$p";
  elif command -v apt-get >/dev/null 2>&1; then apt-get -y install "$p";
  elif command -v zypper >/dev/null 2>&1; then zypper -n install "$p"; fi; done; }
tma_svc_off() { for u in "$@"; do systemctl stop "$u" 2>/dev/null; systemctl mask "$u" 2>/dev/null; done; return 0; }
tma_ts=$(date +%Y%m%d%H%M%S)
tma_bak() { [ -e "$1" ] || return 0; ls "$1".tmaegis.bak.* >/dev/null 2>&1 || cp -a "$1" "$1.tmaegis.bak.$tma_ts"; }
tma_applied() { return 0; }
PAMF="/etc/pam.d/system-auth /etc/pam.d/password-auth /etc/pam.d/system-password /etc/pam.d/common-auth /etc/pam.d/common-password /etc/pam.d/common-account /etc/pam.d/common-session /etc/pam.d/common-session-noninteractive /etc/pam.d/postlogin"
# tma_pam_sed EXPR : sed -E on every existing PAM stack file (follows symlinks, backs up once)
tma_pam_sed() { for f in $PAMF /usr/share/pam-configs/unix; do
  [ -e "$f" ] || continue; tma_bak "$f"; sed -i --follow-symlinks -E "$1" "$f"; done; }
# tma_conf_set FILE KEY VALUE : "key = value", replacing active or commented key lines
tma_conf_set() { f=$1; k=$2; v=$3; mkdir -p "$(dirname "$f")"; [ -e "$f" ] || : > "$f"; tma_bak "$f"
  sed -i -E "/^[[:space:]]*#?[[:space:]]*$k[[:space:]]*=/d" "$f"; printf '%s = %s\n' "$k" "$v" >> "$f"; }
tma_conf_del() { for f in $2; do [ -e "$f" ] || continue; tma_bak "$f"; sed -i -E "/^[[:space:]]*$1[[:space:]]*=/d" "$f"; done; }
# keep yescrypt where present, otherwise force sha512 on password lines
tma_pam_sed '/^[[:space:]]*password[[:space:]].*pam_unix\.so/ { /(sha512|yescrypt)/! { s/[[:space:]]+(md5|bigcrypt|blowfish|sha256|des)\b//g; s/$/ sha512/ } }'
if [ -f /etc/login.defs ]; then tma_bak /etc/login.defs
  grep -Eqi '^[[:space:]]*ENCRYPT_METHOD[[:space:]]+(SHA512|YESCRYPT)\b' /etc/login.defs || {
    sed -i -E '/^[[:space:]]*ENCRYPT_METHOD[[:space:]]/d' /etc/login.defs; echo 'ENCRYPT_METHOD SHA512' >> /etc/login.defs; }
fi
if [ -f /etc/libuser.conf ]; then tma_bak /etc/libuser.conf; sed -i -E 's/^[[:space:]]*crypt_style[[:space:]]*=.*/crypt_style = sha512/' /etc/libuser.conf; fi
true

set -u
export DEBIAN_FRONTEND=noninteractive
tma_pkg_remove() { for p in "$@"; do
  if command -v dnf >/dev/null 2>&1; then dnf -y remove "$p";
  elif command -v yum >/dev/null 2>&1; then yum -y remove "$p";
  elif command -v apt-get >/dev/null 2>&1; then apt-get -y purge "$p";
  elif command -v zypper >/dev/null 2>&1; then zypper -n remove "$p"; fi; done; }
tma_pkg_install() { for p in "$@"; do
  if command -v dnf >/dev/null 2>&1; then dnf -y install "$p";
  elif command -v yum >/dev/null 2>&1; then yum -y install "$p";
  elif command -v apt-get >/dev/null 2>&1; then apt-get -y install "$p";
  elif command -v zypper >/dev/null 2>&1; then zypper -n install "$p"; fi; done; }
tma_svc_off() { for u in "$@"; do systemctl stop "$u" 2>/dev/null; systemctl mask "$u" 2>/dev/null; done; return 0; }
tma_ts=$(date +%Y%m%d%H%M%S)
tma_bak() { [ -e "$1" ] || return 0; ls "$1".tmaegis.bak.* >/dev/null 2>&1 || cp -a "$1" "$1.tmaegis.bak.$tma_ts"; }
tma_applied() { return 0; }

tma_logindefs() { k=$1; v=$2; [ -f /etc/login.defs ] || return 0; tma_bak /etc/login.defs
  sed -i -E "/^[[:space:]]*$k[[:space:]]/d" /etc/login.defs; printf '%s\t%s\n' "$k" "$v" >> /etc/login.defs; }
tma_today() { echo $(( $(date +%s) / 86400 )); }
# "user lastchg min max warn inactive" for accounts that have a real password hash
tma_each_pwuser() { awk -F: '$2 ~ /^[^*!xX]/ && $2 != "" {print $1, $3, $4, $5, $6, $7}' /etc/shadow; }
N=365
tma_logindefs PASS_MAX_DAYS $N
t=$(tma_today)
tma_each_pwuser | while read -r u lc mn mx wr ia; do
  # skip anyone the new limit would expire within a week: no surprise lock-outs
  [ -n "$lc" ] && [ "$lc" -gt 0 ] || continue
  [ $((lc + N)) -gt $((t + 7)) ] && chage -M $N "$u"
done
true

