tma_each_pwuser() { awk -F: '$2 ~ /^[^*!xX]/ && $2 != "" {print $1, $3, $4, $5, $6, $7}' /etc/shadow; }
N=30
[ -f /etc/default/useradd ] || { mkdir -p /etc/default; : > /etc/default/useradd; }
tma_bak /etc/default/useradd
sed -i -E '/^[[:space:]]*INACTIVE=/d' /etc/default/useradd; echo "INACTIVE=$N" >> /etc/default/useradd
t=$(tma_today)
tma_each_pwuser | while read -r u lc mn mx wr ia; do
  # only where the password is not already expired, so -I cannot lock anyone out now
  if [ -z "$mx" ] || [ "$mx" -ge 99999 ]; then chage -I $N "$u"
  elif [ -n "$lc" ] && [ $((lc + mx + N)) -gt $t ]; then chage -I $N "$u"; fi
done
true

set -u
export DEBIAN_FRONTEND=noninteractive
tma_pkg_remove() { for p in "$@"; do
  if command -v dnf >/dev/null 2>&1; then dnf -y remove "$p";
  elif command -v yum >/dev/null 2>&1; then yum -y remove "$p";
  elif command -v apt-get >/dev/null 2>&1; then apt-get -y purge "$p";
  elif command -v zypper >/dev/null 2>&1; then zypper -n remove "$p"; fi; done; }
tma_pkg_install() { for p in "$@"; do
  if command -v dnf >/dev/null 2>&1; then dnf -y install "$p";
  elif command -v yum >/dev/null 2>&1; then yum -y install "$p";
  elif command -v apt-get >/dev/null 2>&1; then apt-get -y install "$p";
  elif command -v zypper >/dev/null 2>&1; then zypper -n install "$p"; fi; done; }
tma_svc_off() { for u in "$@"; do systemctl stop "$u" 2>/dev/null; systemctl mask "$u" 2>/dev/null; done; return 0; }
today=$(date +%F)
awk -F: '$2 ~ /^\$.+\$/ {print $1}' /etc/shadow | while read -r u; do
  l=$(chage --list "$u" 2>/dev/null | sed -n 's/^Last password change[^:]*: //p')
  case "$l" in never|"") continue;; esac
  [ "$(date -d "$l" +%s 2>/dev/null || echo 0)" -gt "$(date +%s)" ] && chage -d "$today" "$u"
done
true

set -u
export DEBIAN_FRONTEND=noninteractive
tma_pkg_remove() { for p in "$@"; do
  if command -v dnf >/dev/null 2>&1; then dnf -y remove "$p";
  elif command -v yum >/dev/null 2>&1; then yum -y remove "$p";
  elif command -v apt-get >/dev/null 2>&1; then apt-get -y purge "$p";
  elif command -v zypper >/dev/null 2>&1; then zypper -n remove "$p"; fi; done; }
