  elif command -v apt-get >/dev/null 2>&1; then apt-get -y install "$p";
  elif command -v zypper >/dev/null 2>&1; then zypper -n install "$p"; fi; done; }
tma_svc_off() { for u in "$@"; do systemctl stop "$u" 2>/dev/null; systemctl mask "$u" 2>/dev/null; done; return 0; }
findmnt -kn /tmp >/dev/null 2>&1 && exit 0
if ! grep -qE '^[^#][^[:space:]]*[[:space:]]+/tmp[[:space:]]' /etc/fstab; then
  cp -a /etc/fstab /etc/fstab.tmaegis.bak.$(date +%Y%m%d%H%M%S)
  echo 'tmpfs /tmp tmpfs defaults,rw,nosuid,nodev,noexec,relatime 0 0' >> /etc/fstab
fi
systemctl unmask tmp.mount 2>/dev/null; systemctl daemon-reload 2>/dev/null
mount /tmp 2>/dev/null || mount -t tmpfs -o rw,nosuid,nodev,noexec,relatime tmpfs /tmp; true

